import{_ as e,o as l,c as a,a3 as i}from"./chunks/framework.EDt1A0Ag.js";const c=JSON.parse('{"title":"评测方法论与质检标准 | 全球机场 (AirportMatrix)","description":"AirportMatrix 独立实验室测试流程、网络量化指标体系、晚高峰压测标准与流媒体/AI风控解锁验证方案。","frontmatter":{"title":"评测方法论与质检标准 | 全球机场 (AirportMatrix)","description":"AirportMatrix 独立实验室测试流程、网络量化指标体系、晚高峰压测标准与流媒体/AI风控解锁验证方案。"},"headers":[],"relativePath":"methodology.md","filePath":"methodology.md","lastUpdated":1791019698000}'),r={name:"methodology.md"};function o(s,t,n,d,g,h){return l(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="📊-评测方法论与质检标准" tabindex="-1">📊 评测方法论与质检标准 <a class="header-anchor" href="#📊-评测方法论与质检标准" aria-label="Permalink to &quot;📊 评测方法论与质检标准&quot;">​</a></h1><p>为了彻底摒除主观臆测与商业营销滤镜，<strong>全球机场 (AirportMatrix)</strong> 制定了严谨的标准化网络评测体系。本文档全面公开我们的评测环境、数据采集流程、质量量化模型与加权评分算法。</p><hr><h2 id="🔬-评测分级与标准化核验流程" tabindex="-1">🔬 评测分级与标准化核验流程 <a class="header-anchor" href="#🔬-评测分级与标准化核验流程" aria-label="Permalink to &quot;🔬 评测分级与标准化核验流程&quot;">​</a></h2><p>考虑到市场品牌数量众多且部分历史品牌官方入口变动频繁，本站对收录品牌采用<strong>两轨分级披露流程</strong>，拒绝将未实测档案混充深度实测：</p><h3 id="轨道-a-实测原图验证梯队-18-家含测速-解锁原图" tabindex="-1">轨道 A：实测原图验证梯队（18 家含测速/解锁原图） <a class="header-anchor" href="#轨道-a-实测原图验证梯队-18-家含测速-解锁原图" aria-label="Permalink to &quot;轨道 A：实测原图验证梯队（18 家含测速/解锁原图）&quot;">​</a></h3><ol><li><strong>公开套餐核对与测速归档</strong>：采集标准公开套餐定价（严格区分为「年付折算」与「真实月付」），保留 <code>MAI-TEST-BOT</code>、<code>MiaoKo</code>、<code>MiaoSu</code> 等工具跑出的节点测速图或流媒体解锁图，<strong>完整保留测试时间（精确到日/时分）、后端运营商（如珠海联通 5Gbps/9Gbps）及测试样本量</strong>。</li><li><strong>非晚高峰测试隔离标注</strong>：若补充引用 <code>2026-10-19</code> 等非晚高峰时段测速数据，页面内均明确注明“非晚高峰参考表现（20:00–23:00 晚高峰可能存在回落）”。</li><li><strong>客户端与风控适配核查</strong>：对照各服务商支持的协议（SS / SS2022 / VLESS / Trojan / Hysteria2）核验第三方主流客户端与自研端兼容情况。</li></ol><h3 id="轨道-b-品牌档案与待核实梯队-无图参考-后排-13-家" tabindex="-1">轨道 B：品牌档案与待核实梯队（无图参考 / 后排 13 家） <a class="header-anchor" href="#轨道-b-品牌档案与待核实梯队-无图参考-后排-13-家" aria-label="Permalink to &quot;轨道 B：品牌档案与待核实梯队（无图参考 / 后排 13 家）&quot;">​</a></h3><ul><li>对具备完整近期套餐资料但暂缺实测原图的精选品牌（如暮光加速、隐形人、Firefly 等），标记为「参考表 / 品牌资料」，不伪造晚高峰速度曲线；</li><li>对历史清单中缺少近期连续实测记录、或官方最新入口与价目待确认的后排品牌，严格标为「待核实」，并取消精确小数评分。</li></ul><hr><h2 id="📐-五大核心量化指标与判定阈值" tabindex="-1">📐 五大核心量化指标与判定阈值 <a class="header-anchor" href="#📐-五大核心量化指标与判定阈值" aria-label="Permalink to &quot;📐 五大核心量化指标与判定阈值&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">指标维度</th><th style="text-align:left;">采集工具与方法</th><th style="text-align:left;">优秀阈值（A 级）</th><th style="text-align:left;">可用阈值（B 级）</th><th style="text-align:left;">警戒阈值（C 级）</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>晚高峰丢包率</strong></td><td style="text-align:left;">MTR 连续 500 次 ICMP/TCP 探测 (20:30-22:30)</td><td style="text-align:left;">&lt; 1.0%</td><td style="text-align:left;">1.0% ~ 5.0%</td><td style="text-align:left;">&gt; 8.0%</td></tr><tr><td style="text-align:left;"><strong>延迟抖动 (Jitter)</strong></td><td style="text-align:left;">分布式探针连续计算延迟标准差 ($\\sigma$)</td><td style="text-align:left;">$\\sigma \\le 5\\text{ms}$</td><td style="text-align:left;">$5\\text{ms} &lt; \\sigma \\le 20\\text{ms}$</td><td style="text-align:left;">$\\sigma &gt; 40\\text{ms}$</td></tr><tr><td style="text-align:left;"><strong>单线程吞吐</strong></td><td style="text-align:left;">YouTube 4K/8K 视频首帧与 Connection Speed</td><td style="text-align:left;">$\\ge 80,000\\text{ Kbps}$</td><td style="text-align:left;">$30,000 \\sim 80,000\\text{ Kbps}$</td><td style="text-align:left;">$&lt; 15,000\\text{ Kbps}$</td></tr><tr><td style="text-align:left;"><strong>IP 欺诈分 (Fraud)</strong></td><td style="text-align:left;">IPQualityScore / Scamalytics 风险库检索</td><td style="text-align:left;">$\\text{Score} &lt; 15$</td><td style="text-align:left;">$15 \\le \\text{Score} &lt; 40$</td><td style="text-align:left;">$\\text{Score} \\ge 60$</td></tr><tr><td style="text-align:left;"><strong>节点可用率 (SLA)</strong></td><td style="text-align:left;">7×24 小时每 5 分钟健康心跳探活</td><td style="text-align:left;">$\\ge 99.5%$</td><td style="text-align:left;">$98.0% \\sim 99.5%$</td><td style="text-align:left;">$&lt; 95.0%$</td></tr></tbody></table><hr><h2 id="🛠️-底层拓扑鉴别标准" tabindex="-1">🛠️ 底层拓扑鉴别标准 <a class="header-anchor" href="#🛠️-底层拓扑鉴别标准" aria-label="Permalink to &quot;🛠️ 底层拓扑鉴别标准&quot;">​</a></h2><p>市场中存在大量以“廉价中转”冒充“专线”的现象。实验室采用严格的物理时延常数进行技术甄别：</p><ul><li><strong>真 IPLC / IEPL 专线</strong>： <ul><li>上海 - 日本物理延迟约为 $25\\text{ms} \\sim 32\\text{ms}$；</li><li>深圳 - 香港物理延迟约为 $4\\text{ms} \\sim 7\\text{ms}$；</li><li>全天 24 小时延迟波动稳定在 $\\pm 2\\text{ms}$ 以内，不经过公网国际出口路由器（如 202.97 或 59.43），晚高峰零丢包。</li></ul></li><li><strong>公网中继（Transit Tunnel）</strong>： <ul><li>国内入口通过公网中转服务器汇聚，再经公网 163 骨干网出海；</li><li>晚高峰延迟显著上浮（+30ms 至 +100ms），丢包率超过 5%~15%。</li></ul></li><li><strong>直连线路（Direct BGP）</strong>： <ul><li>无国内中转入口，客户端直连海外节点；</li><li>易受运营商 QOS 流量整形与 DNS 污染影响，稳定性随地区和时段波动极大。</li></ul></li></ul><hr><h2 id="🤖-ai-工具与流媒体解锁测试方案" tabindex="-1">🤖 AI 工具与流媒体解锁测试方案 <a class="header-anchor" href="#🤖-ai-工具与流媒体解锁测试方案" aria-label="Permalink to &quot;🤖 AI 工具与流媒体解锁测试方案&quot;">​</a></h2><p>海外高端平台对机房 IP 实施严格的风控阻断。我们的验证规范如下：</p><h3 id="_1-openai-chatgpt-解锁检测" tabindex="-1">1. OpenAI / ChatGPT 解锁检测 <a class="header-anchor" href="#_1-openai-chatgpt-解锁检测" aria-label="Permalink to &quot;1. OpenAI / ChatGPT 解锁检测&quot;">​</a></h3><ul><li>访问 <code>chatgpt.com</code> 与 <code>api.openai.com</code>；</li><li>验证是否出现 Cloudflare Turnstile 循环人机验证或 <code>Access Denied</code> (1020/403)；</li><li>验证是否被降级至 <code>GPT-4o mini</code> 限制模式或阻断登录；</li><li>判定标准：纯净住宅双 ISP IP &gt; 原生机房双 ISP IP &gt; 广播机房 IP。</li></ul><h3 id="_2-流媒体全解锁检测" tabindex="-1">2. 流媒体全解锁检测 <a class="header-anchor" href="#_2-流媒体全解锁检测" aria-label="Permalink to &quot;2. 流媒体全解锁检测&quot;">​</a></h3><ul><li><strong>Netflix</strong>：必须能播放地区限定非自制版权剧（例如日区、韩区独立版权番剧），而非仅能播放 Netflix Originals 自制剧；</li><li><strong>Disney+</strong>：必须能正常加载首页海报流并无报错开启 4K HDR 杜比视界码流；</li><li><strong>YouTube Premium</strong>：定位地区与免翻广政策需精准匹配。</li></ul><hr><h2 id="⚖️-综合评级加权算法" tabindex="-1">⚖️ 综合评级加权算法 <a class="header-anchor" href="#⚖️-综合评级加权算法" aria-label="Permalink to &quot;⚖️ 综合评级加权算法&quot;">​</a></h2><p>每篇评测的总评分依据以下加权公式严格计算：</p><p>$$\\text{Final Score} = S_{\\text{稳定}} \\times 0.35 + S_{\\text{速度}} \\times 0.25 + S_{\\text{解锁}} \\times 0.20 + S_{\\text{性价比}} \\times 0.15 + S_{\\text{易用}} \\times 0.05$$</p><ul><li><strong>网络稳定性 ($35%$)</strong>：晚高峰丢包表现、多运营商（电信/联通/移动）互通性、SLA 探活历史。</li><li><strong>速度与带宽 ($25%$)</strong>：高峰期突发带宽、大文件拉取速率、YouTube 4K 秒开缓冲。</li><li><strong>解锁与纯净度 ($20%$)</strong>：住宅双 ISP 占比、流媒体跨区完整度、AI 工具风控豁免率。</li><li><strong>性价比与售后 ($15%$)</strong>：月付门槛、工单响应时效、Telegram 运维交流群透明度。</li><li><strong>客户端支持 ($5%$)</strong>：一键订阅转换、主流核心适配文档完整度。</li></ul><hr><h2 id="📌-数据有效期与版本声明" tabindex="-1">📌 数据有效期与版本声明 <a class="header-anchor" href="#📌-数据有效期与版本声明" aria-label="Permalink to &quot;📌 数据有效期与版本声明&quot;">​</a></h2><ul><li><strong>评测周期</strong>：每季度对排行榜核心品牌进行数据复测；</li><li><strong>重大变动触发</strong>：若遇国际海底光缆中断、大规模出口波动或品牌主控更换，实验室将在 7 个工作日内启动加急重测并在对应评测页面标注更新；</li><li><strong>历史归档</strong>：历史版本测速记录移入归档库，保障长期可信度与读者知情权。</li></ul>',31)])])}const u=e(r,[["render",o]]);export{c as __pageData,u as default};
